) AS (
  VALUES 
    (178::BIGINT, 'Una maravilla por completo, realmente no es necesario que le guste leer, solo lo básico con las lecturas que se hace, pero con investigar las obras y participar en clase, pasa el curso de lo más bien. Lo recomiendo demsiado para la actividad cultural porque la va a pasar bien y disfrutar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'ec9ba327a09d83e33b1f1867fe34a7c8f78634a3d3867bfd395fe1f464486933'::TEXT, ARRAY[503]::BIGINT[]),
    (178::BIGINT, 'Las evaluaciones principales son grupales, prepárese para ver películas en clase y participe siempre que pueda ya que es algo que el profe valora mucho. En general todo es muy chill hasta que llega el proyecto final (un filme corto) y también muy disfrutable si te gusta el cine. Muy recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '248557028da86d371cb41eb17fdfce589892a5e32c12d6673273836aa77fa288'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Super buen profesor, no es necesario que le guste leer para llevar el curso. Los trabajos no consumen demasiado tiempo. El profesor entiende que este es un curso de 0 créditos y se está bajo la carga académica del TEC. Las clases son entretenidas, el profe es una persona increíble y ama su trabajo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-24T00:00:00+00:00'::TIMESTAMPTZ, '4699237c61f66616c5abf40e19783d93fd9588a90d1fbcd5bf8afe023e98047e'::TEXT, ARRAY[503]::BIGINT[]),
    (178::BIGINT, 'Es una teja de profesor y persona. Se nota que le gusta su trabajo, y le interesa que los estudiantes aprendan. Tampoco pide que lean un montón de libros porque es consciente que no tenemos tiempo, pero le gusta mucho conversar con los estudiantes y conocerlos. Ayuda bastante con el proyecto final.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '9b21a864f096016cecac9cc8181131057dc18d922babd1d84de09e1d160b6780'::TEXT, ARRAY[503]::BIGINT[]),
    (178::BIGINT, 'Yo matriculé con miedo solo porque me quedaba bien en el horario pero yo no leo. Afortunadamente la clase no se trata de leer al final jajajaj. Si son lectores pueden conversar con el profe por horas de horas, y si les cuadra el teatro por años. Es una gran persona y lo ayuda a uno a pasar la clase.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-09T00:00:00+00:00'::TIMESTAMPTZ, 'a46e8766d7dbdb0e9ad329fd41128cc510a98d06cc61a5e82add62fbe318d793'::TEXT, ARRAY[503]::BIGINT[]),
    (178::BIGINT, 'Excelente profe, lo único es que no crea que va a ir a leer, si se lee, pero el trabajo final es presentar un escrito hecho por usted Si no le gusta escribir mejor vuélvalo a pensar antes de matricular con él, fuera de eso las clases son super interesantes, el profe sabe de todo y le gusta compartir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, '990ac909bcd22fc72243714b19c3669a2d4017a1a63aacfaadf5cbb805eb086c'::TEXT, ARRAY[503]::BIGINT[]),
    (178::BIGINT, 'El profe es una persona muy profesional y como apasionado de la literatura da muy buenas recomendaciones. Da la clase desde un enfoque para nada dedicado a leer obras enteras, si no a conocer escritores y conocer nuevas perspectivas. Excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-01T00:00:00+00:00'::TIMESTAMPTZ, '622fe6e0d66c84e17c9147838b47b248c1abee2a442dc946e3ec219a0bd93538'::TEXT, ARRAY[503]::BIGINT[]),
    (178::BIGINT, 'Muy mala nota, muchas playadas en clase'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, '6473d3d035c1be242e418ff870e3d020fbff678a779dc4b80e80ce35d927099c'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Llevé Artes Dramáticas con él en verano y sus clases fueron muy interesantes; además, ayuda mucho durante las clases. No es estricto para calificar. Recomendado 100 %.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'ec91888002c1d285f4f5dcc7caed56f74ceb85f1b052a8110363ae82e42d79dc'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'Yo desearía haberme quedado y de alguna manera repetir jsjsjs bromis. Un excelente profesor y una excelente persona. Usted opine en las clases que eso es lo más divertido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'a2e847bfed5b79195a5f0fc794ca183a0bce197bf54d876a651c5ed993f138f0'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Las clases con él son muy interesantes y uno aprende mucho pero siento que para una cultural es mucha la carga de trabajos y proyectos. Así que si sabe que va a tener un semestre duro no matricule con él porque va a ser peor. Pero a pesar de todo el profe cae muy bien y pone películas buenas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, '1faa92cd243bff14828b3e55b3ff50a9833f0ae6807791875177debd703f71f5'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Clases muy entretenidas, el profesor pone películas que se adaptan a los gustos de la clase, deja una cantidad media de tareas, pero nada del otro mundo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '72d7782ebc976d7d92a0c634942635ea24346ab3c0bba6ec5ba9394c20ecdadb'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Cuidado, bastantes trabajos extra-clase. El profesor es super buena gente y durante el curso uno ve muchas películas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '08c5bfc5e5f566f83f95be496d2ab93d214c6fce2a2e4098971017b1e814bd41'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Deja bastantes trabajillos cortos, pero nada del otro mundo. El profesor es muy buena persona y se aprende mucho con él. La participación le importa muchísimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Inspirador']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '24c2b70e5c21af0d34cd4b07495c814204de4fbe954e32079ba21d10a15b388e'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'bea97f678a2108f6b741d93a5fc5a32f38dc60c345d7c61d4a8381b8bd96548b'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'El curso es muy entretenido. El profesor siempre intenta que la clase sea diferente creando dinámicas nuevas. Suele ser muy comprensivo con el resto de cursos. Le encanta el tema por lo que siempre busca que sus estudiantes participen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b50845b7a7e26a8320cd86bd4aaf5ad0a94bd4a3ae8ad749410299477180da4c'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Es muy pasional con su curso, es muy compresivo, como persona es excelente, el curso es fácil, si has hecho teatro te encantará, pero para ser 0 créditos el curso exige mucho hasta cierto punto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '0cc0a726dc7d724ebe0ea67cf35b52e24c661e9b2e65a6052a2c853a17fb6b10'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'El profe es demasiado carismático, no califica para nada duro. Hace la clase entretenida. Se pasa fácil y se disfruta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, '9985a765ab7760dbca81b9bbba17299f4bdf3152d7f46324448b9ac384231aed'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Muy buen profesor. Las películas son entretenidas y se aprende mucho de cine. Las tareas y trabajitos no son complicados, solo hay que ponerle al cortometraje del proyecto final, ya que eso sí toma su tiempo. Muy buena opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-12-27T00:00:00+00:00'::TIMESTAMPTZ, '490250a5b8425065843eaf732161c3a6b81a5cf5d5f174121bdfdb28ca1a495b'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Definitivamente el mejor, en especial porque en la primera clase nos preguntó por los gustos en películas, entonces en sí, nos pone películas que ha todos nos gusta y las tareas que deja, son para que uno exponga su punto de vista y se exprese, solo cansado los dos proyectos pero el resto, fácil'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '8d6a2f22f4a638b621a713f87ca960a6524f93f802ca638f0ea7bf099d91ad55'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Súper buen profe, súper buena nota, siempre disponible para ayudar y súper comprensivo. Deja pocos trabajos y son relativamente sencillos si se presta atención a la clase. Se disfruta mucho el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '248812494fba156bd9ccc03354dbcba9e6206cec376b5f5f4088be6e7b221763'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Uno de los mejores del departamento de cultura y deporte, una calidad de persona y buen profesor, si te gusta el cine esta clase te encantara, tal vez con el video sea lo mas tedioso, pero el resto de trabajos son fáciles, recomiendo mucho la participación en su clase.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'fcf2c8353c9ff899518423c4a93366d536f5394a206e0a318895a2f1dc963e61'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Excelente profesor. Demuestra altos conocimientos en la materia. Se adaptó bien a la metodología virtual. Los trabajos algunas veces quitan bastante tiempo, pero son interesantes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'a64ee0a3f23301a3c423099c3b66e548bb1fe6db20a8caed78472293580c9852'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Es un excelente profesor, se nota su conocimiento del cine. Siempre esta pendiente de que todos entiendan. Los trabajos difíciles fueron el ensayo y el video, pero nada imposible. No califica duro, eso si muestre interés en su clase. Si piensa llevar Apreciación del cine, ESCOJA A ESTE PROFE.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '5b35c5ac82a0c2a7262b4b81829cc78a7108f08c14d148cb9ab38e60b382fe35'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Excelente profesor y persona, ama lo que hace y es bueno en ello, es muy atento, comprensivo e inspiracional. El curso es sencillo, desestresante y divertido. Si hubiera Artes dramáticas II lo llevaría con él. Por la virtualidad se pierde un poco la magia de la obra final pero él lo manejó muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'da02493e2b8f3e07dbcb69bcfc2cc8a2d67fe5d3c726a81271441507b5ff56ed'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'Excelente profe, tareas y trabajos sencillos con los que se aprende bastante y se disfruta un montón. Súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '24b637e6ff17dc764855405c5ddb979c04d2227504e84c676b7cf53328d9a578'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'De los mejores profes que he tenido. Muy buena persona, comprensivo y paciente. Deja bastantes tareas simples pero realmente se aprende demasiado del cine.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-01-20T00:00:00+00:00'::TIMESTAMPTZ, '99eec2bed7844b5258f6df7b9532aa877276c7194820f247e2edd9473920cac0'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'El es el mejor profesor de la virtualidad, el curso es muy sencillo y el profesor entiende muy bien lo de la virtualidad y trata de hacer el curso lo menos pesado posible, recomendadisimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'a0b9b44aef26485fd8cbd7e0970544ed3ff514fa7d8ff5fd830349a2a1e9e083'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '127d743e36457f14743dd03dcf6389dc562416514555e084829388b14bb9112a'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Excelente profe, muy atento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '1582807ebaf312753f9f2a6ff9cd1ca397e5ee5a4647d3c48b48a95ea75c6f0e'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Recomendado 10/10 este profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '0c0aca0608baff2dbfb55053a7d09bf9dc8ea257611677b86eed219b615064b8'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'El profe es muy buena nota, el curso lo ayuda a desarrollar destrezas de comunicación e interacción. El profe es muy amable y la verdad se nota que le gusta lo que hace, de los mejores profes que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '80fd580b96f3bc7b23b038483b75501b5b94fd49c6bc6555c354dd3ea37d2e8e'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'Excelente clase, excelente grupo, excelente profe! Si puede tomar Artes Dramáticas con él, hágalo. Su clase es para relajarse y expresarse. Ama el teatro y lo que uno aprende con él, es para la vida!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'fc66eddfa2545dfd36f333a88e836ee89f630767ecbec9fe6e3e4940bc311ad7'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'Sin duda deja muchas tareas pero son PELÍCULAS. Disfrute el curso y haga el guión lo más pronto posible así no tiene presión a final de semestre. Es DEMASIADO comprensivo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '050f264389a9c2c17fbfb12df3d28cd91494750f1be72692e361315d52cb72a2'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Es muy buen profe. Es super amable y siempre esta dispuesto a entender. La clase es muy muy facil y si alguien quiere aprender el enseña muy bien y si alguien quiere pasar facil tambien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '0d7202ba7cec98e5913c2b2b910b4dd30947805cd5a6fd178a6017c323fa6065'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'El profe es el mejor, te transmite una confianza gigante y se preocupa mucho por cada estudiante. Es sumamente comprensivo, en modalidad virtual trata de hacer las clases lo más dinámicas posibles y se nota mucho su esfuerzo. Trata de hacer que el curso no demande mucho tiempo. Matriculen con él!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '19ec4eca18606950d421a4aac4b5b4408a4e984c17f768a467eac0251c396fc2'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'Llevar Artes Dramáticas con Arnoldo es de lo mejor. Arnoldo es una teja de persona, siempre es muy comprensivo y está abierto a cualquier idea que uno tenga. La participación y creatividad importa mucho en sus clases, no califica rudo, pero es un excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2020-07-17T00:00:00+00:00'::TIMESTAMPTZ, '4bc5b9d38a61891aa917c9750a38856b8da7011c51c375fadfa65d77102acd51'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'Teatro fue genial con él, realmente sabe como ayudarle a desenvolverse.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-10-22T00:00:00+00:00'::TIMESTAMPTZ, '99fdb9bce9f7a31991cd1d2085ae5d2b5f656c874b06fb522609c21b22570b0c'::TEXT, ARRAY[692]::BIGINT[]),
    (178::BIGINT, 'Es un profesor muy bueno, ademas de ser muy comprensivo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-12T00:00:00+00:00'::TIMESTAMPTZ, 'f49ca1a03efd2e6954caae8764a25d02456da133ad4a71d3998187a49884e40a'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Para ser un curso de 0 créditos deja muchos trabajos y si no es amante del cine se va a aburrir. Se pasa facil'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'bb95492b7257e1a46eb85f0424caf005ad2564b2cab1ab72432ec888b80a0521'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'El curso va recomendado para los amantes del cine (aunque tal vez ya hayan visto las pelis). Las películas son muy interesantes y generan conversación para rato. Lo único negativo es que deja tareas, no son la gran cosa, pero si busca solo ir y ya, este tal vez no sea el curso. Igual es fácil.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'f13ebe83ea8171d04da7afa95ee0b4da761b9f46081ac27b68da29890505c4e1'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Es un crack, aunque deja bastante carga de trabajos para ser un curso de 0 créditos, pero es bastante flexible!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-29T00:00:00+00:00'::TIMESTAMPTZ, '7b28c09f390cea1433e2fcec46ebaa1cad755781dab1c11784438b0bdd3dd7f8'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Es un crack, explica súper bien pero deja bastantes trabajos para ser una clase de 0 créditos. Uno la pasa muy bien y se aprende mucho, es una persona muy culta e inteligente. Si simplemente va a llevar una cultural para "salir de eso" no lo haga con él ya que deja bastantes tareas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '8a50081fc1ef07971bde62634824cd51b2c5d3adcecc2c7c36540574947a74ec'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd315b77f5aa9c3b3391e9ee555e93896854a258c20436620677d3fbed3efc8c5'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Bastantes trabajos y lo peor es que son 0 créditos. Aunque igual le recomiendo que si le conviene por el horario lo meta, de fijo lo pasa.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, '596bf2961b3d113e9cd2f7a5794711469ea2bffb87462fff993a12ee4754c029'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Buena gente, flexible e inteligente. Su clase es fácil de pasar y no califica duro.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2017-06-09T00:00:00+00:00'::TIMESTAMPTZ, '69ca8ba051192fbb26e365e6111d21679c9885b8164d9cd4b9a032be2b3bab7e'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'De los mejores profes que he conocido. Sus clases son buenisimas, pone peliculas interesantes y tiene un vasto conocimiento de todos los temas. Si puede meter con él hagalo, pone trabajos pero no califica duro, es flexible y son divertidos de hacer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-05-29T00:00:00+00:00'::TIMESTAMPTZ, '7b1c5b8cfd90b814fb608e102889f0b2f9ea8a636d38ece7ab8b79f7799b723a'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Excelente profesor, super gracioso y apoyador! El único error fue ponernos a ver "Arrival" pero por todo lo demás excelente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2017-05-07T00:00:00+00:00'::TIMESTAMPTZ, '1539fa86984d068dc1013457876be356338c52d84b656442d24ddd626509586e'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '966c3811e10b673d32409df57b9485ed6b784feb42c752089c14e595f08016bd'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Es muy justo, se va a divertir bastante y es muy responsable en los ensayos para los grupos de teatro.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'c3ca4aa8cbbfdce53ff509a47d9be28e3acaa35fe14fb11a215a6471cd17d69a'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'Excelente persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-05-21T00:00:00+00:00'::TIMESTAMPTZ, 'ec824f0d8ee161678c9e40b1d7d00f96c57a5caa4ce30da9bd69f5a8e0a77d13'::TEXT, ARRAY[498]::BIGINT[]),
    (178::BIGINT, 'El único problema es que complica mucho el curso para ser de 0 créditos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-22T00:00:00+00:00'::TIMESTAMPTZ, '1b53d4233b49d14d923ab73f5534d5e5061f09a37c31cde1f8e776930b1204a7'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'El mejor! Demasiado Pura vida también'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-18T00:00:00+00:00'::TIMESTAMPTZ, '5ff88f7445f7f09ed16e66a6e5afbc99608576a5f42c7f718e8362641cd79743'::TEXT, ARRAY[504]::BIGINT[]),
    (178::BIGINT, 'Apreciacion de cine vale la pena matricurla con el, pone ciertas tareillas propias del curso y proyecto final. Pero a pesar de todo hizo del curs algo muy pintorezco. Como persona es una teja. Recomendado!!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'bf07c83ccba0df849f3509d6c6369514401db09e8a0cd4fff418d894654b7064'::TEXT, ARRAY[504]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
